{
  "format": "genereti-guide",
  "version": 1,
  "id": "interactive-output-views",
  "title": "Interactive output views",
  "summary": "Present a working sketch or document without losing interaction.",
  "steps": [
    {
      "title": "Use the sketch",
      "text": "Click the p5 output; its click counter changes. The moving circle follows your pointer.",
      "target": {
        "nodeType": "GeneretiLivecode",
        "part": "preview"
      }
    },
    {
      "title": "Hide just the node chrome",
      "text": "Select p5 and press Alt+O, or Shift-click its overlay button. Only output remains. Hover just outside an edge to reveal its opacity and stacking controls. The restore glyph brings the chrome back.",
      "target": {
        "nodeType": "GeneretiLivecode",
        "part": "node"
      }
    },
    {
      "title": "Move it into an overlay",
      "text": "Restore the node, then press Alt+W or click the overlay button normally. The same sketch moves into an interactive overlay.",
      "target": {
        "nodeType": "GeneretiLivecode",
        "part": "toolbar"
      },
      "check": {
        "kind": "overlay-open"
      }
    },
    {
      "title": "Arrange two views",
      "text": "Open the scrollable document overlay too. Hover a view and use Cmd+[ / ] for backward/forward, or Cmd+Shift+[ / ] for back/front. The bar has the same controls; Shift-click a stacking arrow for back/front. Code editors keep their own bracket shortcuts."
    },
    {
      "title": "Annotate and present",
      "text": "The drawing node keeps the active editor in both views. Alt+Shift+O toggles click-through. Alt+F fills an overlay inside Comfy; Alt+P hides graph/code and Alt+Shift+Z hides the outer Comfy shell. Native browser fullscreen remains separate.",
      "target": {
        "nodeType": "GeneretiDrawing",
        "part": "preview"
      }
    }
  ]
}

