{
  "format": "genereti-guide",
  "version": 1,
  "id": "opentouch-basics",
  "title": "Textures, signals and tables",
  "summary": "Edit an expression, connect a control signal, and use a table as a parameter source.",
  "steps": [
    {
      "title": "One graph, three interfaces",
      "text": "TOP carries images, CHOP carries sampled channels, and DAT carries documents and tables. The lesson workflow uses real nodes you can keep editing.",
      "target": {
        "nodeType": "GeneretiTextureExpression",
        "part": "node"
      }
    },
    {
      "title": "Write a texture expression",
      "text": "Change the expression, for example change x*12 to x*8. CodeMirror applies it while typing. The GPU program recompiles only when its source changes.",
      "target": {
        "nodeType": "GeneretiTextureExpression",
        "part": "code",
        "widget": "expression"
      },
      "check": {
        "kind": "changed-widget"
      }
    },
    {
      "title": "Change a signal",
      "text": "Adjust oscillator frequency. The FLOAT output is the last sample of its first channel; the channel output carries the whole named block.",
      "target": {
        "nodeType": "GeneretiChopOscillator",
        "part": "parameter",
        "widget": "frequency"
      },
      "check": {
        "kind": "changed-widget"
      }
    },
    {
      "title": "A FLOAT becomes a texture control",
      "text": "Follow the wire from chop.lag to top.transform rotate. These are regular Comfy input sockets; signals update the live shader without a Python queue.",
      "target": {
        "nodeType": "GeneretiTextureTransform",
        "part": "node"
      },
      "check": {
        "kind": "connected-input",
        "input": "rotate"
      }
    },
    {
      "title": "A table becomes a parameter",
      "text": "Edit a number in the table. dat.cell selects one cell and exposes it as STRING and FLOAT. The lesson wires its FLOAT into top.math value.",
      "target": {
        "nodeType": "GeneretiDatTable",
        "part": "code",
        "widget": "text"
      },
      "check": {
        "kind": "changed-widget"
      }
    },
    {
      "title": "GPU composition and history",
      "text": "Inspect feedback, corner pin and compositing. Feedback keeps two GPU textures and avoids cyclic graph wires. Its history exists in Live mode; Queue returns the current input.",
      "target": {
        "nodeType": "GeneretiTextureFeedback",
        "part": "preview"
      }
    },
    {
      "title": "Keep 3D in Three.js",
      "text": "The Three.js Livecode source uses the same IMAGE path. Its code can read inputTexture and declared CHOP-driven parameters; no separate geometry engine is needed.",
      "target": {
        "nodeType": "GeneretiLivecode",
        "part": "code"
      }
    },
    {
      "title": "Read and export the report",
      "text": "The DAT document contains the library report. Use its export controls for Markdown, standalone HTML, or Print / Save as PDF. The report describes performance and device boundaries.",
      "target": {
        "nodeType": "GeneretiDatText",
        "part": "toolbar"
      }
    }
  ]
}
